<?php
namespace App\Service;
use App\Entity\Conversation;use App\Entity\GroupeMember;use App\Entity\User;use App\Repository\ConversationParticipantRepository;use App\Repository\GroupeMemberRepository;use Symfony\Component\Security\Core\Exception\AccessDeniedException;
final class ConversationAccessService{public function __construct(private readonly ConversationParticipantRepository $participants,private readonly GroupeMemberRepository $members){}public function canAccess(Conversation $c,User $u):bool{if($u->getStatus()!=='ACTIVE')return false;if($c->getType()===Conversation::FACTION)return $c->getGroup()?->isActive()===true&&$this->members->findActive($c->getGroup(),$u)!==null;return $this->participants->findFor($c,$u)!==null;}public function assertAccess(Conversation $c,User $u):void{if(!$this->canAccess($c,$u))throw new AccessDeniedException('Vous n’avez plus accès à cette conversation.');}public function canModerate(Conversation $c,User $u):bool{if(in_array($u->getRole(),['MODERATOR','ADMIN'],true))return true;if($c->getType()!==Conversation::FACTION||$c->getGroup()===null)return false;$m=$this->members->findActive($c->getGroup(),$u);return $m?->isAdmin()===true;}}
